namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string ImageEmoji { get; set; } = "🍽️";
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Emoji { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
    }

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Breakfast", Emoji = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Emoji = "🥗", Description = "Midday meals that keep you going" },
        new() { Name = "Dinner", Emoji = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Emoji = "🍰", Description = "Sweet treats to satisfy your cravings" },
        new() { Name = "Snacks", Emoji = "🍿", Description = "Quick bites for any time of day" },
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            ImageEmoji = GetCategoryEmoji(submission.Category),
        });
    }

    private string GetCategoryEmoji(string category) => category.ToLower() switch
    {
        "breakfast" => "🥞",
        "lunch" => "🥗",
        "dinner" => "🍝",
        "desserts" => "🍰",
        "snacks" => "🍿",
        _ => "🍽️",
    };

    private static List<Recipe> GetSeedRecipes() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast", ImageEmoji = "🥞",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups all-purpose flour", "2 eggs", "1½ cups milk", "¼ cup melted butter", "2 tbsp sugar", "1 tbsp baking powder", "½ tsp salt"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
            TotalRatings = 12, RatingSum = 52,
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast", ImageEmoji = "🥑",
            Description = "Simple, healthy, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Red pepper flakes", "Salt and pepper", "Optional: poached egg"],
            Steps = ["Toast the bread until golden and crispy.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and optional poached egg."],
            TotalRatings = 8, RatingSum = 35,
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch", ImageEmoji = "🥗",
            Description = "A crisp, tangy classic that never goes out of style.",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "1 lemon", "Black pepper"],
            Steps = ["Wash and chop romaine into bite-sized pieces.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze fresh lemon on top and season with pepper."],
            TotalRatings = 6, RatingSum = 25,
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch", ImageEmoji = "🌯",
            Description = "A protein-packed wrap that's great for meal prep.",
            Ingredients = ["2 flour tortillas", "1 grilled chicken breast, sliced", "1 cup mixed greens", "¼ cup ranch dressing", "½ cup shredded cheese", "1 tomato, diced"],
            Steps = ["Warm tortillas in a dry pan.", "Layer chicken, greens, tomato, and cheese on each tortilla.", "Drizzle with ranch dressing.", "Roll up tightly, tucking in the sides."],
            TotalRatings = 4, RatingSum = 17,
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner", ImageEmoji = "🍝",
            Description = "A rich, meaty sauce over perfectly cooked pasta.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 garlic cloves, minced", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper", "Parmesan for serving"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, then drain excess fat.", "Sauté onion and garlic until soft.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
            TotalRatings = 15, RatingSum = 68,
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner", ImageEmoji = "🍳",
            Description = "A quick weeknight dinner loaded with vegetables.",
            Ingredients = ["2 chicken breasts, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 garlic cloves, minced", "1 tsp ginger, grated", "Cooked rice for serving"],
            Steps = ["Mix soy sauce, sesame oil, and cornstarch in a bowl.", "Cook chicken in a hot wok until browned.", "Add garlic and ginger, stir for 30 seconds.", "Add vegetables and cook for 3–4 minutes.", "Pour in sauce and toss until everything is coated.", "Serve over steamed rice."],
            TotalRatings = 10, RatingSum = 43,
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", ImageEmoji = "🍪",
            Description = "Crispy edges, chewy centers — the ultimate cookie.",
            Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
            Steps = ["Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour, baking soda, and salt.", "Fold in chocolate chips.", "Scoop onto baking sheets.", "Bake at 375°F (190°C) for 9–11 minutes."],
            TotalRatings = 20, RatingSum = 94,
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Snacks", ImageEmoji = "🥑",
            Description = "Fresh, zesty, and perfect with chips.",
            Ingredients = ["3 ripe avocados", "1 lime, juiced", "½ onion, diced", "1 jalapeño, minced", "¼ cup cilantro, chopped", "1 tomato, diced", "Salt and pepper"],
            Steps = ["Mash avocados to desired consistency.", "Stir in lime juice, onion, jalapeño, and cilantro.", "Fold in diced tomato.", "Season with salt and pepper.", "Serve immediately with tortilla chips."],
            TotalRatings = 9, RatingSum = 40,
        },
    ];
}

