    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
    }

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Breakfast", Emoji = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Emoji = "🥗", Description = "Midday meals that keep you going" },
        new() { Name = "Dinner", Emoji = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Emoji = "🍰", Description = "Sweet treats to satisfy your cravings" },
        new() { Name = "Snacks", Emoji = "🍿", Description = "Quick bites for any time of day" },
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
