toolArgs.file_text:
@* Star rating widget — interactive component *@
@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _selectedRating ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                @(star <= _selectedRating ? "★" : "☆")
            </span>
        }
    </div>
    @if (_hasRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    @if (AverageRating > 0)
    {
        <span class="rating-info">@AverageRating.ToString("0.0") avg (@TotalRatings ratings)</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int TotalRatings { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private bool _hasRated;

    private async Task Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        await OnRated.InvokeAsync(stars);
    }
}

