toolArgs.file_text:
@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

@{ var recipes = RecipeService.GetRecipesByCategory(CategoryName); }

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">
        No recipes in this category yet. <a href="/submit">Be the first to submit one!</a>
    </div>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <span class="recipe-emoji">@recipe.ImageEmoji</span>
                <div class="recipe-info">
                    <h3>@recipe.Title</h3>
                    <p>@recipe.Description</p>
                    @if (recipe.TotalRatings > 0)
                    {
                        <span class="recipe-rating">★ @recipe.AverageRating.ToString("0.0") (@recipe.TotalRatings ratings)</span>
                    }
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
}

.recipe-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.recipe-card {
    display: flex;
    align-items: center;
    gap: 1.25rem;
    padding: 1.25rem;
    border: 1px solid #e9ecef;
    border-radius: 12px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
