toolArgs.file_text:
@page "/recipe/{RecipeId:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category.ToLower()">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <div class="recipe-header">
        <span class="recipe-hero-emoji">@_recipe.ImageEmoji</span>
        <div>
            <h1>@_recipe.Title</h1>
            <p class="recipe-description">@_recipe.Description</p>
        </div>
    </div>

    <div class="rating-section">
        <h4>Rate this recipe</h4>
        <RecipeHub.Components.Shared.StarRating
            RecipeId="@_recipe.Id"
            AverageRating="@_recipe.AverageRating"
            TotalRatings="@_recipe.TotalRatings"
            OnRated="HandleRating" />
    </div>

    <div class="recipe-body">
        <div class="ingredients-section">
            <h2>🧾 Ingredients</h2>
            <ul>
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>

        <div class="steps-section">
            <h2>👩‍🍳 Steps</h2>
            <ol>
                @foreach (var step in _recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

.recipe-header {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.recipe-hero-emoji {
    font-size: 4rem;
}

.recipe-header h1 {
    margin: 0;
}

.recipe-description {
    color: #6c757d;
    font-size: 1.1rem;
    margin: 0.25rem 0 0;
}

.rating-section {
    padding: 1.25rem;
    background: #f8f9fa;
    border-radius: 12px;
    margin-bottom: 2rem;
}

.rating-section h4 {
    margin: 0 0 0.75rem;
}

.recipe-body {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

@media (max-width: 768px) {
    .recipe-body {
        grid-template-columns: 1fr;
    }
}

.ingredients-section, .steps-section {
    padding: 1.25rem;
    border: 1px solid #e9ecef;
    border-radius: 12px;
}

.ingredients-section h2, .steps-section h2 {
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.ingredients-section ul {
    padding-left: 1.25rem;
}

.ingredients-section li, .steps-section li {
    margin-bottom: 0.5rem;
    line-height: 1.5;
}

.steps-section ol {
    padding-left: 1.25rem;
}

